refentry.refsect1:
&reftitle.description;
public mixedPDOStatement::fetch intmodePDO::FETCH_DEFAULT intcursorOrientationPDO::FETCH_ORI_NEXT intcursorOffset0
Recupera una riga da un set di risultati associato a un'istanza di PDOStatement. Il parametro mode determina come PDO restituisce la riga.

&reftitle.returnvalues;

 In caso di successo, il valore restituito da questa funzione dipende dal tipo di fetch. In
 ogni caso, viene restituito &false; in caso di fallimento o se non ci sono altre righe.

  &reftitle.examples;

   Recupero di righe con diversi stili di fetch


<?php
$db = new PDO('sqlite::memory:');
$db->exec("CREATE TABLE fruit (name VARCHAR(100), colour VARCHAR(100))");
$db->exec("INSERT INTO fruit (name, colour) VALUES
                             ('apple', 'red'),
                             ('banana', 'yellow'),
                             ('orange', 'orange'),
                             ('kiwi', 'green')");
$sth = $db->prepare("SELECT name, colour FROM fruit");
$sth->execute();

/* Prova degli stili di PDOStatement::fetch */
echo "PDO::FETCH_ASSOC: ";
echo "Restituisce la riga successiva come array indicizzato per nome di colonna\n";
$result = $sth->fetch(PDO::FETCH_ASSOC);
var_dump($result);
echo "\n";

echo "PDO::FETCH_BOTH: ";
echo "Restituisce la riga successiva come array indicizzato sia per nome sia per numero di colonna\n";
$result = $sth->fetch(PDO::FETCH_BOTH);
var_dump($result);
echo "\n";

echo "PDO::FETCH_LAZY: ";
echo "Restituisce la riga successiva come oggetto PDORow con i nomi delle colonne come proprietà\n";
$result = $sth->fetch(PDO::FETCH_LAZY);
var_dump($result);
echo "\n";

echo "PDO::FETCH_OBJ: ";
echo "Restituisce la riga successiva come oggetto stdClass con i nomi delle colonne come proprietà\n";
$result = $sth->fetch(PDO::FETCH_OBJ);
var_dump($result);
echo "\n";
?>


   &example.outputs;


PDO::FETCH_ASSOC: Restituisce la riga successiva come array indicizzato per nome di colonna
array(2) {
  ["name"]=>
  string(5) "apple"
  ["colour"]=>
  string(3) "red"
}

PDO::FETCH_BOTH: Restituisce la riga successiva come array indicizzato sia per nome sia per numero di colonna
array(4) {
  ["name"]=>
  string(6) "banana"
  [0]=>
  string(6) "banana"
  ["colour"]=>
  string(6) "yellow"
  [1]=>
  string(6) "yellow"
}

PDO::FETCH_LAZY: Restituisce la riga successiva come oggetto PDORow con i nomi delle colonne come proprietà
object(PDORow)#3 (3) {
  ["queryString"]=>
  string(30) "SELECT name, colour FROM fruit"
  ["name"]=>
  string(6) "orange"
  ["colour"]=>
  string(6) "orange"
}

PDO::FETCH_OBJ: Restituisce la riga successiva come oggetto stdClass con i nomi delle colonne come proprietà
object(stdClass)#4 (2) {
  ["name"]=>
  string(4) "kiwi"
  ["colour"]=>
  string(5) "green"
}





   Recupero di righe con un cursore scorrevole


<?php
function readDataForwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY BET';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_NEXT)) {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    }
}
function readDataBackwards($dbh) {
    $sql = 'SELECT hand, won, bet FROM mynumbers ORDER BY bet';
    $stmt = $dbh->prepare($sql, array(PDO::ATTR_CURSOR => PDO::CURSOR_SCROLL));
    $stmt->execute();
    $row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_LAST);
    do {
        $data = $row[0] . "\t" . $row[1] . "\t" . $row[2] . "\n";
        print $data;
    } while ($row = $stmt->fetch(PDO::FETCH_NUM, PDO::FETCH_ORI_PRIOR));
}

print "Lettura in avanti:\n";
readDataForwards($conn);

print "Lettura all'indietro:\n";
readDataBackwards($conn);
?>


   &example.outputs;


Lettura in avanti:
21    10    5
16    0     5
19    20    10

Lettura all'indietro:
19    20    10
16    0     5
21    10    5





   Ordine di costruzione

    Quando gli oggetti vengono recuperati tramite PDO::FETCH_CLASS, le proprietà
    dell'oggetto vengono assegnate per prime e solo dopo viene invocato il costruttore della
    classe. Tuttavia, quando viene indicato anche PDO::FETCH_PROPS_LATE,
    questo ordine è invertito, ossia viene prima chiamato il costruttore e
    successivamente vengono assegnate le proprietà.



<?php
class Person
{
    private $name;

    public function __construct()
    {
        $this->tell();
    }

    public function tell()
    {
        if (isset($this->name)) {
            echo "Sono {$this->name}.\n";
        } else {
            echo "Non ho ancora un nome.\n";
        }
    }
}

$sth = $dbh->query("SELECT * FROM people");
$sth->setFetchMode(PDO::FETCH_CLASS, 'Person');
$person = $sth->fetch();
$person->tell();
$sth->setFetchMode(PDO::FETCH_CLASS|PDO::FETCH_PROPS_LATE, 'Person');
$person = $sth->fetch();
$person->tell();
?>


   &example.outputs.similar;


Sono Alice.
Sono Alice.
Non ho ancora un nome.
Sono Bob.
